<?php
namespace App\Http\Controllers;use Illuminate\Http\{RedirectResponse,Request};use Illuminate\Support\Facades\Auth;use Illuminate\View\View;
class AuthController extends Controller{public function showLogin():View{return view('auth.login');}public function login(Request $request):RedirectResponse{$credentials=$request->validate(['email'=>['required','email'],'password'=>['required','string']]);if(!Auth::attempt($credentials,$request->boolean('remember')))return back()->withErrors(['email'=>'Credenciales incorrectas.'])->onlyInput('email');if(!Auth::user()->estado){Auth::logout();$request->session()->invalidate();return back()->withErrors(['email'=>'La cuenta está inactiva.']);}$request->session()->regenerate();return redirect()->intended('/'.Auth::user()->role.'/dashboard');}public function logout(Request $request):RedirectResponse{Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect('/login');}}
